  "Each figure links to the public document it came from.": "हर आँकड़ा उस सार्वजनिक दस्तावेज़ से जुड़ा है जहाँ से वह आया।",
  "Each official figure is shown with its source and date, next to audit findings and moderated citizen check-ins.": "हर आधिकारिक आँकड़ा अपने स्रोत और तारीख़ के साथ, ऑडिट निष्कर्षों और जाँची गई नागरिक रिपोर्टों के बगल में दिखता है।",
  "Each official figure sits next to audit findings and verified citizen check-ins, with the source and date.": "हर आधिकारिक आँकड़ा ऑडिट निष्कर्षों और सत्यापित नागरिक जाँच के बगल में, स्रोत और तारीख़ के साथ है।",
  "Each official target, such as a functional toilet or a promised possession date, is paired with the matching audit finding or verified citizen check-in.": "हर आधिकारिक लक्ष्य, जैसे चालू शौचालय या कब्ज़े की वादा तारीख़, उससे जुड़े ऑडिट निष्कर्ष या सत्यापित नागरिक जाँच के साथ रखा गया है।",
  "Each public work is shown with its tender specification and warranty beside audit findings and dated citizen photos.": "हर सार्वजनिक काम उसके टेंडर विवरण और वारंटी के साथ, ऑडिट निष्कर्षों और तारीख़ वाली नागरिक फ़ोटो के बगल में दिखता है।",
