  "Estimates are based on rallies, vehicles and advertising observed during the campaign and are published by ADR. They are not a finding by the ECI.": "ये अनुमान प्रचार के दौरान देखी गई रैलियों, वाहनों और विज्ञापनों पर आधारित हैं और ADR ने प्रकाशित किए हैं। ये ECI का निष्कर्ष नहीं हैं।",
  "Evaluates public infrastructure execution performance by penalizing delay duration and cost overruns while weighting physical ground check consensus.": "सार्वजनिक बुनियादी ढाँचे के काम का मूल्यांकन: देरी और लागत वृद्धि पर अंक कटते हैं, और ज़मीनी जाँच की सहमति को महत्व मिलता है।",
  "Every case in Indian district courts is assigned a unique {0}-alphanumeric Case Natural Reference (CNR) number printed at the top-left of every filing receipt or summons.": "भारत की ज़िला अदालतों में हर केस को {0} अंकों-अक्षरों का एक अलग CNR (केस नेचुरल रेफ़रेंस) नंबर मिलता है, जो हर फ़ाइलिंग रसीद या समन के ऊपर बाईं ओर छपा होता है।",
  "Every component has an explicit formula, inputs, weights, and source": "हर हिस्से का साफ़ फ़ॉर्मूला, इनपुट, भार और स्रोत है",
  "Every data ingestion cycle creates a versioned snapshot. If an anomalous update bypasses checks, administrators can instantly revert to a known-good baseline dataset snapshot.": "हर बार डेटा आने पर एक संस्करण वाला स्नैपशॉट बनता है। अगर कोई अजीब अपडेट जाँच से निकल जाए, तो प्रशासक तुरंत पिछले सही स्नैपशॉट पर लौट सकते हैं।",
  "Every figure links to its source. Spotted an error?": "हर आँकड़ा अपने स्रोत से जुड़ा है। कोई गलती दिखी?",
  "Every level from the Centre to the ward or village, and who to approach for a problem.": "केंद्र से लेकर वार्ड या गाँव तक हर स्तर, और किसी समस्या के लिए किससे मिलें।",
  "Every level of government that answers for your PIN code, from the Centre to your ward or village, and who to approach when something goes wrong.": "आपके पिन कोड के लिए ज़िम्मेदार सरकार का हर स्तर, केंद्र से लेकर आपके वार्ड या गाँव तक, और कुछ गड़बड़ हो तो किससे मिलें।",
  "Every module for {0}": "{0} के लिए सभी मॉड्यूल",
  "Every number is sourced": "हर संख्या का स्रोत है",
  "Every number is sourced.": "हर संख्या का स्रोत है।",
  "Every official database, register and audit report we use, with how often it updates, what it misses and the licence it is published under.": "हम जो भी आधिकारिक डेटाबेस, रजिस्टर और ऑडिट रिपोर्ट इस्तेमाल करते हैं, वे सब, साथ में यह कि वे कितनी बार अपडेट होते हैं, उनमें क्या छूटता है और वे किस लाइसेंस के तहत प्रकाशित हैं।",
  "Every pending district court case in India has a unique CNR number allowing instant tracking of daily order sheets and cause lists.": "भारत की ज़िला अदालत के हर लंबित केस का एक अलग CNR नंबर होता है, जिससे रोज़ के आदेश और वाद सूची तुरंत देखी जा सकती है।",
  "Every record links to its primary document and shows when it was last updated, so anyone can check our work.": "हर रिकॉर्ड अपने मूल दस्तावेज़ से जुड़ा है और बताता है कि वह आख़िरी बार कब अपडेट हुआ, ताकि कोई भी हमारा काम जाँच सके।",
  "Every report is reviewed before it is published. Rejected reports are kept for {0} days for abuse checks, then deleted.": "हर रिपोर्ट प्रकाशित होने से पहले जाँची जाती है। अस्वीकृत रिपोर्टें दुरुपयोग जाँच के लिए {0} दिन रखी जाती हैं, फिर हटा दी जाती हैं।",
