  "Generate a legally compliant civic complaint draft citing statutory Citizen Charter SLA resolution hours ({0} hours for garbage, {1} hours for streetlights, {2} hours for potholes).": "नागरिक चार्टर की वैधानिक समय-सीमा (कूड़े के लिए {0} घंटे, स्ट्रीटलाइट के लिए {1} घंटे, गड्ढों के लिए {2} घंटे) के हवाले से क़ानूनी रूप से सही नागरिक शिकायत का मसौदा बनाएँ।",
  "Generate formal violation drafts for illegal open waste burning, construction dust, and industrial smoke for direct submission on CPCB SAMEER & DPCC Green Delhi apps.": "खुले में कूड़ा जलाने, निर्माण की धूल और औद्योगिक धुएँ के उल्लंघन की औपचारिक शिकायत का मसौदा बनाएँ, CPCB समीर और DPCC ग्रीन दिल्ली ऐप पर सीधे जमा करने के लिए।",
  "Generate legally compliant application drafts under Section {0}({1}), Section {2}({3}) First Appeal, or {4}-Hour Life & Liberty provisos.": "धारा {0}({1}), धारा {2}({3}) प्रथम अपील, या {4} घंटे वाले जीवन और स्वतंत्रता प्रावधान के तहत क़ानूनी रूप से सही आवेदन का मसौदा बनाएँ।",
