  "Issuing Body: Comptroller and Auditor General of India (CAG)": "जारी करने वाली संस्था: भारत के नियंत्रक एवं महालेखा परीक्षक (CAG)",
  "Issuing Body: Ministry of Statistics and Programme Implementation (MoSPI), Govt of India": "जारी करने वाली संस्था: सांख्यिकी और कार्यक्रम कार्यान्वयन मंत्रालय (MoSPI), भारत सरकार",
  "It does NOT rank schools as \"good\" or \"bad\"": "यह स्कूलों को \"अच्छा\" या \"बुरा\" रैंक नहीं करता",
  "It does NOT use AI or algorithmic judgment of school quality": "यह स्कूल की गुणवत्ता तय करने के लिए AI या एल्गोरिदम का इस्तेमाल नहीं करता",
  "It is NOT statistically representative of year-round conditions": "यह पूरे साल की स्थिति का सांख्यिकीय रूप से प्रतिनिधि नहीं है",
  "ITO / Supreme Court Air Monitoring Station": "ITO / सुप्रीम कोर्ट वायु निगरानी स्टेशन",
