  "JantaX Citizen Verification Circle #{0}": "JantaX नागरिक सत्यापन मंडल #{0}",
  "JantaX Citizens": "JantaX नागरिक",
  "JantaX Derived Calculations & Indices": "JantaX द्वारा निकाली गई गणनाएँ और सूचकांक",
  "JantaX home": "JantaX होम",
  "JantaX is an independent public data transparency platform aggregating official state RERA records. JantaX does not provide legal advice.": "JantaX एक स्वतंत्र सार्वजनिक डेटा पारदर्शिता मंच है जो राज्य RERA के आधिकारिक रिकॉर्ड एक जगह लाता है। JantaX क़ानूनी सलाह नहीं देता।",
  "JantaX is an independent public data transparency platform aggregating official state RERA records. JantaX does not provide legal advice. All adjudications are sourced directly from competent State RERA Authorities.": "JantaX एक स्वतंत्र सार्वजनिक डेटा पारदर्शिता मंच है जो राज्य RERA के आधिकारिक रिकॉर्ड एक जगह लाता है। JantaX क़ानूनी सलाह नहीं देता। सभी फ़ैसले सीधे सक्षम राज्य RERA प्राधिकरणों से लिए गए हैं।",
  "JantaX is an independent public data transparency platform aggregating official state RERA records. JantaX does not provide legal advice. Never declare a builder fraudulent unless an official competent source establishes that fact.": "JantaX एक स्वतंत्र सार्वजनिक डेटा पारदर्शिता मंच है जो राज्य RERA के आधिकारिक रिकॉर्ड एक जगह लाता है। JantaX क़ानूनी सलाह नहीं देता। जब तक कोई सक्षम आधिकारिक स्रोत यह साबित न करे, किसी बिल्डर को धोखेबाज़ न कहें।",
  "JantaX is independent and is not a government portal. Check anything consequential with the publishing authority.": "JantaX स्वतंत्र है और सरकारी पोर्टल नहीं है। कोई भी ज़रूरी बात प्रकाशित करने वाले प्राधिकारी से जाँच लें।",
  "JantaX is independent and is not a government portal. It does not replace official records. Check anything consequential with the publishing authority.": "JantaX स्वतंत्र है और सरकारी पोर्टल नहीं है। यह आधिकारिक रिकॉर्ड की जगह नहीं लेता। कोई भी ज़रूरी बात प्रकाशित करने वाले प्राधिकारी से जाँच लें।",
  "JantaX lists offices, not the people holding them, because office-holders change and we only publish what we can source. Find current names through the links on each card. Titles differ between states and sometimes within one; if something here is wrong for your area,": "JantaX पदों की सूची देता है, उन पर बैठे लोगों की नहीं, क्योंकि पदाधिकारी बदलते रहते हैं और हम वही प्रकाशित करते हैं जिसका स्रोत हो। मौजूदा नाम हर कार्ड के लिंक से देखें। पदों के नाम राज्यों में, और कभी-कभी एक ही राज्य में, अलग होते हैं; अगर आपके क्षेत्र के लिए यहाँ कुछ गलत है,",
  "JantaX never automatically publishes suspicious dataset updates. Updates with confidence scores below {0}%, schema anomalies, or high rejection rates are quarantined for human auditor review.": "JantaX संदिग्ध डेटासेट अपडेट कभी अपने आप प्रकाशित नहीं करता। {0}% से कम भरोसा स्कोर, स्कीमा में गड़बड़ी या बहुत ज़्यादा अस्वीकृति वाले अपडेट मानवीय जाँच के लिए रोक दिए जाते हैं।",
  "JantaX Official Action Layer:": "JantaX आधिकारिक कार्रवाई परत:",
  "JantaX provides structured grievance drafting and tracking integration with official government portals (CPGRAMS / State IPGRS). JantaX never pretends to submit a complaint unless connected via an authorized direct API gateway.": "JantaX शिकायत का मसौदा बनाने और आधिकारिक सरकारी पोर्टलों (CPGRAMS / राज्य IPGRS) पर ट्रैक करने में मदद करता है। जब तक अधिकृत सीधे API से न जुड़ा हो, JantaX शिकायत जमा करने का दिखावा नहीं करता।",
  "JantaX puts official Indian government data beside what was found on the ground, for every PIN code. It is independent, non-partisan and free to use.": "JantaX हर पिन कोड के लिए भारत सरकार का आधिकारिक डेटा ज़मीन पर मिली जानकारी के बगल में रखता है। यह स्वतंत्र, निष्पक्ष और मुफ़्त है।",
  "JantaX starts from a PIN code, because that is how people think about where they live. From there we pull the records that apply to that area, show when they were last updated, and set them next to audit findings and citizen reports so the gap between the claim and the reality is visible.": "JantaX पिन कोड से शुरू करता है, क्योंकि लोग अपने रहने की जगह इसी तरह सोचते हैं। वहाँ से हम उस क्षेत्र पर लागू रिकॉर्ड लाते हैं, दिखाते हैं कि वे आख़िरी बार कब अपडेट हुए, और उन्हें ऑडिट निष्कर्षों और नागरिक रिपोर्टों के बगल में रखते हैं ताकि दावे और हकीकत का अंतर दिखे।",
  "JantaX · Public records for every PIN code": "JantaX · हर पिन कोड के सार्वजनिक रिकॉर्ड",
