  "No citizen reports yet": "अभी तक कोई नागरिक रिपोर्ट नहीं",
  "No claims recorded for this filter": "इस फ़िल्टर के लिए कोई दावा दर्ज नहीं",
  "No data": "डेटा नहीं",
  "No login is needed to read any page.": "कोई भी पेज पढ़ने के लिए लॉगिन की ज़रूरत नहीं।",
  "No login. No OTP. Official portals lie; a photo of a washed out road or locked PHC does not.": "न लॉगिन, न OTP। आधिकारिक पोर्टल गलत हो सकते हैं; बह गई सड़क या बंद PHC की फ़ोटो नहीं।",
  "No machine-readable feed. Import a file: npm run data -- sync cag-audit-findings --file <path> (template: data/templates/cag-audit-findings.csv). Curated by hand from reports on cag.gov.in: one row per paragraph, quoting the finding and linking the report PDF. Every row needs the report, paragraph and link.": "कोई मशीन-पठनीय फ़ीड नहीं। फ़ाइल आयात करें: npm run data -- sync cag-audit-findings --file <path> (टेम्पलेट: data/templates/cag-audit-findings.csv)। cag.gov.in की रिपोर्टों से हाथ से तैयार: हर पैराग्राफ़ की एक पंक्ति, निष्कर्ष का उद्धरण और रिपोर्ट PDF का लिंक। हर पंक्ति में रिपोर्ट, पैराग्राफ़ और लिंक ज़रूरी है।",
  "No machine-readable feed. Import a file: npm run data -- sync candidate-affidavits --file <path> (template: data/templates/candidate-affidavits.csv). Compile from affidavits on affidavit.eci.gov.in (one row per candidate, with the affidavit link). If you use a compiled source such as ADR/MyNeta, check its reuse terms first.": "कोई मशीन-पठनीय फ़ीड नहीं। फ़ाइल आयात करें: npm run data -- sync candidate-affidavits --file <path> (टेम्पलेट: data/templates/candidate-affidavits.csv)। affidavit.eci.gov.in के हलफ़नामों से तैयार करें (हर उम्मीदवार की एक पंक्ति, हलफ़नामे के लिंक के साथ)। ADR/MyNeta जैसे संकलित स्रोत इस्तेमाल करें तो पहले उनकी पुन: उपयोग शर्तें जाँचें।",
  "No machine-readable feed. Import a file: npm run data -- sync cppp-awards --file <path> (template: data/templates/cppp-awards.csv). Download award of contract (AOC) listings from eprocure.gov.in/cppp or the state portal and fill the template, one row per award, with the notice link in sourceUrl.": "कोई मशीन-पठनीय फ़ीड नहीं। फ़ाइल आयात करें: npm run data -- sync cppp-awards --file <path> (टेम्पलेट: data/templates/cppp-awards.csv)। eprocure.gov.in/cppp या राज्य पोर्टल से अनुबंध आवंटन (AOC) सूचियाँ डाउनलोड करें और टेम्पलेट भरें, हर आवंटन की एक पंक्ति, sourceUrl में सूचना का लिंक।",
  "No machine-readable feed. Import a file: npm run data -- sync polling-stations --file <path> (template: data/templates/polling-stations.csv). Each state CEO website publishes polling station lists per assembly constituency (usually PDF or Excel). Convert them to the template and import with --file.": "कोई मशीन-पठनीय फ़ीड नहीं। फ़ाइल आयात करें: npm run data -- sync polling-stations --file <path> (टेम्पलेट: data/templates/polling-stations.csv)। हर राज्य के CEO की वेबसाइट विधानसभा क्षेत्रवार मतदान केंद्रों की सूची (आमतौर पर PDF या Excel) प्रकाशित करती है। इन्हें टेम्पलेट में बदलें और --file से आयात करें।",
  "No machine-readable feed. Import a file: npm run data -- sync rera-projects --file <path> (template: data/templates/rera-projects.csv). Export the registered project list from each state RERA portal (for example MahaRERA or UP RERA) and map it to the template. Most portals block automated scraping, so import files by hand.": "कोई मशीन-पठनीय फ़ीड नहीं। फ़ाइल आयात करें: npm run data -- sync rera-projects --file <path> (टेम्पलेट: data/templates/rera-projects.csv)। हर राज्य RERA पोर्टल (जैसे MahaRERA या UP RERA) से पंजीकृत परियोजनाओं की सूची निकालें और टेम्पलेट से मिलाएँ। ज़्यादातर पोर्टल स्वचालित स्क्रैपिंग रोकते हैं, इसलिए फ़ाइलें हाथ से आयात करें।",
  "No machine-readable feed. Import a file: npm run data -- sync ward-services --file <path> (template: data/templates/ward-services.csv). Cities publish ward figures on their own dashboards or on smartcities.data.gov.in. Compile one row per ward into the template.": "कोई मशीन-पठनीय फ़ीड नहीं। फ़ाइल आयात करें: npm run data -- sync ward-services --file <path> (टेम्पलेट: data/templates/ward-services.csv)। शहर वार्ड के आँकड़े अपने डैशबोर्ड या smartcities.data.gov.in पर प्रकाशित करते हैं। हर वार्ड की एक पंक्ति टेम्पलेट में भरें।",
  "No official datasets with figures for": "इसके लिए आँकड़ों वाला कोई आधिकारिक डेटासेट नहीं:",
