  "Official counts may lag actual teacher deployments by {0}-{1} months. Para-teacher data updated quarterly.": "आधिकारिक गिनती असल शिक्षक तैनाती से {0}-{1} महीने पीछे हो सकती है। पैरा-शिक्षक डेटा हर तिमाही अपडेट होता है।",
  "Official data connected:": "आधिकारिक डेटा जुड़ा:",
  "Official datasets are pulled from APIs (CPPP, UDISE+, HMIS, CPCB) or parsed from published PDFs (CAG reports, RERA orders). Every raw file is hashed so later changes can be detected.": "आधिकारिक डेटासेट API (CPPP, UDISE+, HMIS, CPCB) से लिए जाते हैं या प्रकाशित PDF (CAG रिपोर्टें, RERA आदेश) से पढ़े जाते हैं। हर मूल फ़ाइल का हैश बनता है ताकि बाद के बदलाव पकड़े जा सकें।",
  "Official datasets for this module are set up but not connected yet": "इस मॉड्यूल के आधिकारिक डेटासेट तैयार हैं पर अभी जुड़े नहीं",
