  "Set LGD_DISTRICTS_URL to the download link. On lgdirectory.gov.in choose Download Directory, then All Districts of India, as CSV. Import the file with --file, or set LGD_DISTRICTS_URL to a stable copy.": "LGD_DISTRICTS_URL में डाउनलोड लिंक डालें। lgdirectory.gov.in पर Download Directory, फिर All Districts of India को CSV के रूप में चुनें। फ़ाइल को --file से आयात करें, या LGD_DISTRICTS_URL में एक स्थिर प्रति का लिंक डालें।",
  "Set MPLADS_WORKS_URL to the download link. On the MPLADS portal, export the works report for the constituencies you cover, and import it with --file, or set MPLADS_WORKS_URL to a stable export link.": "MPLADS_WORKS_URL में डाउनलोड लिंक डालें। MPLADS पोर्टल पर अपने क्षेत्रों की कार्य रिपोर्ट निकालें और --file से आयात करें, या MPLADS_WORKS_URL में स्थिर एक्सपोर्ट लिंक डालें।",
  "Set OBI_STATE_BUDGET_RESOURCE to the CKAN resource id. Open Budgets India runs CKAN: open the state budget dataset, open its data table resource and copy the resource id from the URL.": "OBI_STATE_BUDGET_RESOURCE में CKAN resource id डालें। Open Budgets India CKAN पर चलता है: राज्य बजट डेटासेट खोलें, उसका डेटा तालिका resource खोलें और URL से resource id कॉपी करें।",
