  "We have not matched any school or public-works record to this PIN.": "हमने इस पिन से किसी स्कूल या सार्वजनिक काम का रिकॉर्ड नहीं मिलाया है।",
  "We map the six digits to a district and state, then find every school, clinic, project, court and office that serves it.": "हम छह अंकों को ज़िले और राज्य से मिलाते हैं, फिर वहाँ की सेवा करने वाले हर स्कूल, क्लिनिक, परियोजना, अदालत और कार्यालय को ढूँढते हैं।",
  "We never allege wrongdoing against a contractor, builder or office on our own.": "हम अपनी ओर से किसी ठेकेदार, बिल्डर या कार्यालय पर गड़बड़ी का आरोप नहीं लगाते।",
  "We place claims and audits side by side. We do not editorialise.": "हम दावे और ऑडिट आमने-सामने रखते हैं। अपनी राय नहीं जोड़ते।",
  "We quote audit reports and official documents and link to the original. We do not make accusations of our own.": "हम ऑडिट रिपोर्टों और आधिकारिक दस्तावेज़ों को उद्धृत करते हैं और मूल का लिंक देते हैं। अपनी ओर से आरोप नहीं लगाते।",
  "We rate-limit requests by a hashed network address to stop scraping. The raw address is not stored.": "स्क्रैपिंग रोकने के लिए हम नेटवर्क पते के हैश से अनुरोधों को सीमित करते हैं। मूल पता सहेजा नहीं जाता।",
  "We remove location, time and device metadata from photos before storing them. Faces and number plates are blurred before publication.": "फ़ोटो सहेजने से पहले हम उनकी लोकेशन, समय और डिवाइस की जानकारी हटा देते हैं। प्रकाशन से पहले चेहरे और नंबर प्लेट धुँधले किए जाते हैं।",
  "We resolve it to your district and pull every matching record from UDISE+, HMIS, PMGSY, RERA, NJDG and more.": "हम इसे आपके ज़िले से मिलाते हैं और UDISE+, HMIS, PMGSY, RERA, NJDG और अन्य स्रोतों से हर मेल खाता रिकॉर्ड लाते हैं।",
  "We show claims and audits side by side and do not editorialise.": "हम दावे और ऑडिट आमने-सामने दिखाते हैं और अपनी राय नहीं जोड़ते।",
