  "When the live records service cannot be reached we show bundled sample data so the site keeps working. Those figures are illustrative and are labelled as such.": "जब लाइव रिकॉर्ड सेवा नहीं मिलती, तो साइट चलती रहे इसलिए हम साथ रखा नमूना डेटा दिखाते हैं। वे आँकड़े उदाहरण हैं और उन पर यही लिखा होता है।",
